SELECT no_plan();
CREATE TEMP TABLE cof_renewal_fixture(booking_id uuid,period_id uuid,next_period uuid,token text,submission uuid,attempt jsonb,authorization_id uuid,admin_user uuid,booking_snapshot jsonb);
GRANT ALL ON cof_renewal_fixture TO service_role;
DO $$ DECLARE b public.bookings%ROWTYPE; admin_user uuid; planned jsonb; pid uuid; nxt uuid; BEGIN
 SELECT * INTO b FROM public.bookings WHERE reservation_number='ZNX-000150';
 SELECT user_id INTO admin_user FROM public.profiles WHERE is_admin LIMIT 1;
 PERFORM set_config('request.jwt.claims',jsonb_build_object('sub',admin_user,'role','authenticated')::text,true);
 planned:=public.admin_schedule_rental_extension(b.id,b.end_date+60,b.dropoff_time,158400,true,'Synthetic card-on-file renewal test');
 PERFORM public.admin_activate_rental_extension((planned->>'plan_id')::uuid);
 SELECT id INTO pid FROM public.rental_extension_periods WHERE extension_plan_id=(planned->>'plan_id')::uuid ORDER BY period_number LIMIT 1;
 SELECT id INTO nxt FROM public.rental_extension_periods WHERE extension_plan_id=(planned->>'plan_id')::uuid ORDER BY period_number OFFSET 1 LIMIT 1;
 UPDATE public.rental_extension_periods SET period_start=current_date+7,period_end=current_date+37,billing_reminder_date=current_date WHERE id=nxt;
 INSERT INTO cof_renewal_fixture SELECT b.id,pid,nxt,NULL,gen_random_uuid(),NULL,NULL,admin_user,to_jsonb(x) FROM public.bookings x WHERE x.id=b.id;
END $$;
SET LOCAL ROLE service_role;
UPDATE cof_renewal_fixture SET token=ensure_square_renewal_link(period_id);
SELECT ok((SELECT jsonb_array_length(get_square_checkout_authorization_context('renewal',token)->'rental_schedule')>=2 FROM cof_renewal_fixture),'Authorization snapshots applicable server rental schedule');
UPDATE cof_renewal_fixture SET attempt=prepare_square_cof_checkout('renewal',token,submission,'{"givenName":"Other","familyName":"Cardholder","email":"otherpayer@example.invalid","postalCode":"10003","country":"US"}','zonyx-square-cof-v1',repeat('terms ',30),get_square_checkout_authorization_context('renewal',token),true,true,'location');
UPDATE cof_renewal_fixture SET authorization_id=(attempt->>'authorization_id')::uuid;
SELECT is((SELECT attempt->>'amount_cents' FROM cof_renewal_fixture),'158400','Renewal keeps exactly $1584');
SELECT ok((SELECT test_id IS NULL AND booking_id=(SELECT booking_id FROM cof_renewal_fixture) FROM square_renewal_payment_attempts WHERE id=(SELECT (attempt->>'id')::uuid FROM cof_renewal_fixture)),'Existing public renewal retains original reservation association');
SELECT is((SELECT payer_email FROM square_checkout_authorizations WHERE id=(SELECT authorization_id FROM cof_renewal_fixture)),'otherpayer@example.invalid','Saved customer belongs to actual payer, not assumed guest');
UPDATE square_checkout_authorizations SET square_customer_id='customer-payer' WHERE id=(SELECT authorization_id FROM cof_renewal_fixture);
SELECT claim_square_cof_dispatch(authorization_id,submission) FROM cof_renewal_fixture;
SELECT record_square_checkout_payment((attempt->>'id')::uuid,'renewal-square-id',158400,'location','live','COMPLETED') FROM cof_renewal_fixture;
SELECT confirm_square_checkout_card(authorization_id,'customer-payer','ccof:renewal','2222','VISA') FROM cof_renewal_fixture;
SELECT is((SELECT get_public_square_renewal_details(token)->>'can_pay' FROM cof_renewal_fixture),'false','Paid renewal cannot be collected twice');
UPDATE rental_extension_periods SET amount_due_cents=158500 WHERE id=(SELECT next_period FROM cof_renewal_fixture);
SELECT throws_like('SELECT prepare_square_authorized_renewal(authorization_id,next_period,admin_user,''location'') FROM cof_renewal_fixture','%not included in the recorded authorization%','Changed future amounts require new customer authorization');
UPDATE rental_extension_periods SET amount_due_cents=158400 WHERE id=(SELECT next_period FROM cof_renewal_fixture);
SELECT is((SELECT prepare_square_authorized_renewal(authorization_id,next_period,admin_user,'location')->>'dispatch' FROM cof_renewal_fixture),'true','Recorded authorization supports a subsequent due merchant-initiated renewal');
SELECT is((SELECT prepare_square_authorized_renewal(authorization_id,next_period,admin_user,'location')->>'dispatch' FROM cof_renewal_fixture),'false','Repeated merchant instruction cannot dispatch duplicate charge');
SELECT is((SELECT to_jsonb(b) FROM bookings b WHERE id=(SELECT booking_id FROM cof_renewal_fixture)),(SELECT booking_snapshot FROM cof_renewal_fixture),'Card storage and future claim preserve original booking/deposit fields');
SELECT is((SELECT count(*)::integer FROM booking_security_deposits),0,'Neither customer checkout nor future saved-card claim creates a HOLD');
SELECT withdraw_square_checkout_authorization(management_token) FROM square_checkout_authorizations WHERE id=(SELECT authorization_id FROM cof_renewal_fixture);
SELECT throws_like('SELECT prepare_square_authorized_renewal(authorization_id,next_period,admin_user,''location'') FROM cof_renewal_fixture','%Active reservation-specific%','Withdrawal blocks subsequent merchant-initiated renewal claims');
RESET ROLE;
